/* Dokument má jeden kód s dvoma volačkami (NOZ) a niekoľko volačiek,
   ktoré patria dvom kódom (JET TIME, RED SEA, GEMINI…). Skupiny sa
   počítajú z CELÉHO zoznamu, aby sa uznala každá platná odpoveď aj
   vtedy, keď je zapnutý filter. */
const CS_BY_ICAO = {}, CS_BY_CALL = {};
CALLSIGNS.forEach(cs => {
  (CS_BY_ICAO[cs.icao] = CS_BY_ICAO[cs.icao] || []).push(cs);
  (CS_BY_CALL[cs.call] = CS_BY_CALL[cs.call] || []).push(cs);
});
